if (!int.TryParse(Console.ReadLine(), out var count) || count < 0 || count > 100) Environment.Exit(1);
var shapes = new Shape[count];
for (var i = 0; i < count; i++)
{
    var tokens = (Console.ReadLine() ?? "").Split(' ', StringSplitOptions.RemoveEmptyEntries);
    Shape? shape = null;
    if (tokens.Length == 3 && tokens[0] == "r"
        && int.TryParse(tokens[1], out var width) && int.TryParse(tokens[2], out var height)
        && width >= 0 && height >= 0)
    {
        shape = new Rectangle(width, height);
    }
    else if (tokens.Length == 2 && tokens[0] == "s"
        && int.TryParse(tokens[1], out var side) && side >= 0)
    {
        shape = new Square(side);
    }
    if (shape is null) Environment.Exit(1);
    shapes[i] = shape;
}
long total = 0;
foreach (var shape in shapes)
{
    total += shape.Area();
}
Console.WriteLine(total);

class Shape
{
    public virtual long Area() => 0;
}

class Rectangle : Shape
{
    private readonly long _width;
    private readonly long _height;

    public Rectangle(long width, long height)
    {
        _width = width;
        _height = height;
    }

    public override long Area() => _width * _height;
}

class Square : Rectangle
{
    public Square(long side) : base(side, side)
    {
    }
}
